update pages set contenu = '{"sections":[]}'::jsonb where path = '/implantations/lyon/haute-savoie/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"La maintenance industrielle en Haute-Savoie, de l''Arve au Genevois","mecanisme":"Le département concentre un savoir-faire d''usinage de précision que peu de territoires possèdent, celui du décolletage de la vallée de l''Arve, doublé de la mécatronique du bassin d''Annecy. Et une frontière qui aspire les techniciens vers les salaires suisses. Nous employons, évaluons et encadrons ces profils, pour que vos parcs de tours et de centres d''usinage restent disponibles.","cta":"Faire chiffrer ma maintenance en Haute-Savoie","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 en option, nuits, week-ends et jours fériés."},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients industriels accompagnés, dont plus de 80 réguliers"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, résultats partagés"},{"valeur":"4","libelle":"agences, Lyon siège du groupe, Montréal, Dubaï et Madrid","detail":"Aucune en Haute-Savoie, des techniciens qui s''y déplacent"}]},{"type":"probleme","punchline":"Vous formez un bon électromécanicien, et il part travailler de l''autre côté de la frontière. Dans la vallée de l''Arve, la machine n''est pas le problème : c''est la personne qui sait la régler.","puces":[{"accroche":"La frontière tire les salaires techniques.","texte":"Le Genevois et la Suisse voisine recrutent les mêmes profils que vos ateliers, et vos postes restent ouverts des mois."},{"accroche":"Un atelier de décolletage n''a pas de service maintenance complet.","texte":"Les PME de sous-traitance de précision vivent avec un ou deux polyvalents, et rien derrière eux."},{"accroche":"Le réglage au micron ne pardonne rien.","texte":"Une broche, un axe, une géométrie qui dérive, et c''est le rebut qui augmente avant que la machine ne s''arrête."},{"accroche":"Le retard de production remonte toute la chaîne.","texte":"Automobile, aéronautique, médical : un sous-traitant en retard bloque son donneur d''ordre."},{"accroche":"Les équipements lourds punissent le préventif reporté.","texte":"Presses, extrudeuses, fours de la métallurgie et de la plasturgie : chaque élément d''usure ignoré finit en arrêt long."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Des techniciens salariés, évalués et encadrés","texte":", pas des profils trouvés dans l''urgence."},"benefice":"Vous cessez de dépendre d''un marché de l''emploi qui joue contre les ateliers du bassin."},{"prestation":{"accroche":"Un suivi machine-outil sérieux","texte":"géométrie, broches, transmissions, lubrification, éléments d''usure suivis équipement par équipement."},"benefice":"Le rebut recule avant que la panne n''arrive, et la précision se tient dans la durée."},{"prestation":{"accroche":"Le champ technique complet","texte":"[mécanique](/expertises/mecanique/), [électricité](/expertises/electrique/), [automatisme](/expertises/automatisme/), [robotique](/expertises/robotique/), [hydraulique](/expertises/hydraulique/), [pneumatique](/expertises/pneumatique/), [soudure](/expertises/soudure/)."},"benefice":"Un seul contrat pour des lignes automatisées comme pour un parc de tours."},{"prestation":{"accroche":"Un renfort en pic d''activité ou en remplacement d''une absence","texte":", dimensionné sur la durée réelle."},"benefice":"Vous sécurisez la production sans embauche précipitée ni recrutement bâclé."},{"prestation":{"accroche":"Astreinte 24/24 et 7/7 en option","texte":", tenue par nos techniciens mobiles, comme partout en France ([voir nos implantations](/implantations/lyon/))."},"benefice":"Une alerte du dimanche soir trouve un interlocuteur qui qualifie et mobilise."},{"prestation":{"accroche":"Pas d''enseigne dans votre rue, et c''est assumé","texte":"ni agence ni hub de techniciens dans le département, des professionnels itinérants qui viennent sur site."},"benefice":"Vous payez une organisation qui fonctionne, pas une adresse de plus sur un papier à en-tête."}]},{"type":"deroule","etapes":[{"titre":"La qualification","texte":"Vous décrivez la panne ou le projet au 04 78 33 72 05, l''état de l''installation, l''accès à vos locaux. Rappel dans l''heure aux horaires ouvrés."},{"titre":"La préparation","texte":"Technicien choisi selon la technologie en cause, habilitations et certifications vérifiées, accueil sécurité préparé, pièces anticipées quand le diagnostic le permet."},{"titre":"L''intervention","texte":"Diagnostic, réparation, essais, remise en fonctionnement, dans vos règles de sécurité et votre plan de prévention."},{"titre":"Le contrôle de précision","texte":"Sur machines-outils, reprise des réglages et vérification de la géométrie avant relance de série."},{"titre":"La restitution","texte":"Compte rendu écrit, cause identifiée, recommandations. Vous gardez la connaissance, pas seulement la facture."},{"titre":"La transmission","texte":"Sur demande, nos techniciens partagent avec vos opérateurs ce que le premier niveau doit voir, entendre et signaler."}]},{"type":"garanties","puces":[{"accroche":"Une compétence entretenue, pas seulement recrutée","texte":"chaque technicien suit un parcours de formation au contact des référents du groupe, automatisme, robotique, habilitations et certifications tenues à jour."},{"accroche":"Une sélection prouvée avant l''arrivée","texte":"entretien technique et comportemental, 10 % des candidats retenus, résultats d''évaluation présentés avant la première intervention."},{"accroche":"Un contact unique qui connaît votre dossier","texte":"un chargé d''affaires nommé, une information claire avant, pendant et après chaque mission. Pas de visage différent à chaque visite."}]},{"type":"cta","question":"Besoin de tenir votre parc sans dépendre d''un seul régleur ?","bouton":"Faire chiffrer ma maintenance en Haute-Savoie","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."}]'::jsonb) where path = '/implantations/lyon/haute-savoie/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"preuves","preuves":[{"titre":"Un technicien à temps plein sur un parc multimarques, en 2025","texte":"centres d''usinage, presses et commandes numériques, fabrication de pièces mécaniques de précision","lienLibelle":"Étude de cas VOIT : site du Grand Est","lienHref":"/preuves/voit-grand-est/"},{"titre":"Un technicien de maintenance dédié au maintien d''un parc machines, en 2025","texte":"présence continue, en coordination avec les équipes du site","lienLibelle":"Étude de cas AUTOLIV : maintien d''un site","lienHref":"/preuves/autoliv/"},{"titre":"Des techniciens présents au quotidien dans les équipes de maintenance d''un équipementier automobile, en 2025","texte":"périmètre prioritaire sur les équipements critiques","lienLibelle":"Étude de cas JTEKT : maintenance des installations","lienHref":"/preuves/jtekt/"},{"titre":"3 à 5 techniciens déployés dans plusieurs usines françaises, depuis septembre 2024","texte":"accompagnement d''une montée en cadence","lienLibelle":"Étude de cas VALEO : plusieurs usines","lienHref":"/preuves/valeo-usines/"},{"titre":"Six techniciens sur l''installation et la mise en production d''un parc machines neuf","texte":", site automobile, depuis janvier 2023","lienLibelle":"Étude de cas EATON : mise en production","lienHref":"/preuves/eaton-mise-en-production/"}]},{"type":"objections","questions":[{"question":"Intervenez-vous dans la vallée de l''Arve ?","reponse":"Oui, comme dans tout le département : bassin d''Annecy, Genevois, Chablais, Faucigny. Les ateliers de décolletage y côtoient les usines d''assemblage et les lignes agroalimentaires, et nos techniciens connaissent ces environnements, machines-outils comprises."},{"question":"Quel délai pour une intervention en Haute-Savoie ?","reponse":"Nous ne promettons pas de délai standard : chaque situation est qualifiée d''abord. Ce qui est mesurable, c''est le rappel dans l''heure aux horaires ouvrés, l''astreinte 24/24 et 7/7 en option, et une organisation qui mobilise le bon profil du premier coup."},{"question":"Travaillez-vous avec les PME de sous-traitance de précision ?","reponse":"Oui, et c''est le cas le plus fréquent du bassin : ces ateliers ont rarement un service maintenance complet. Un [technicien en résidence](/offres/residence/) ou quelques visites planifiées par mois suffisent souvent à tenir le parc et à ouvrir l''accès à des compétences rares en cas de coup dur."},{"question":"Combien coûte un contrat de maintenance ?","reponse":"Zéro arrêt est chiffré sur devis, avec trois niveaux de couverture et un engagement type de 6 mois renouvelable. Pour un atelier de sous-traitance, quelques visites planifiées par mois suffisent souvent, et le contrat le dit noir sur blanc. Le diagnostic de départ est gratuit."},{"question":"Pouvez-vous sécuriser un pic d''activité ou couvrir une absence ?","reponse":"Oui. Renfort de vos équipes en saison, remplacement pendant un congé ou un arrêt, accompagnement d''un projet ou d''un transfert de machines : le dispositif se dimensionne sur la durée et les technologies en cause, sans embauche précipitée."},{"question":"Couvrez-vous aussi la Savoie ?","reponse":"Oui, les deux départements, du sillon alpin aux vallées, avec la même méthode et le même suivi. Nos techniciens se déplacent aussi dans l''Isère, la Drôme, la Loire et partout en France, avec un contrat unique."},{"question":"Avez-vous une agence en Haute-Savoie ?","reponse":"Non, ni agence ni hub de techniciens dans le département, et nous ne ferons pas semblant. Nos quatre agences sont Lyon, siège du groupe, Montréal, Dubaï et Madrid. Nos techniciens sont mobiles : ils viennent régler votre machine dans votre atelier, avec un chargé d''affaires qui connaît vos accès."}]},{"type":"ctaFinal","question":"Besoin d''un mainteneur qui tienne un parc de décolletage comme une ligne automatisée ?","bouton":"Faire chiffrer ma maintenance en Haute-Savoie","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]'::jsonb) where path = '/implantations/lyon/haute-savoie/';
